 n=len(ps); z=[[Q(0) for _ in range(4)] for _ in range(4)]
 if n<2 or not support:return {k:list(itertools.chain.from_iterable(z)) for k in ['unit','relative','absolute','joint']},Q(0),Q(0)
 assert len(gaps)==n-1 and all(d>0 for d in gaps)
 mu=sum(gaps,Q(0))/(n-1); h=sum((mu/(mu+d) for d in gaps),Q(0))/(n-1);a=tau/(tau+mu)
 for newer,older in zip(ps[:-1],ps[1:]):
  for i in range(4):
   for j in range(4):z[i][j]+=(older[i]*newer[j]+older[j]*newer[i])/(2*(n-1))
 assert sum(itertools.chain.from_iterable(z),Q(0))==1
 out={k:[Q(1,2)*z[i][j]*g for i in range(4) for j in range(4) if i"'!=j] for k,g in [('"'unit',Q(1)),('relative',h),('absolute',a),('joint',a*h)]}
 return out,h,a
