   assert all(0<=x<=Q(1,2) for values in out.values() for x in values)
   unsupported,_,_=readouts(ps,gaps,0);assert all(x==0 for values in unsupported.values() for x in values)
   count+=1
rng=random.Random(3501)
for _ in range(100):
 n=rng.randint(2,128);ps=[rng.choice(mixtures) for i in range(n)]; gaps=[Q(rng.randint(1,1000000)) for i in range(n-1)]
 out,h,a=readouts(ps,gaps);out2,h2,a2=readouts(ps,[d*Q(13,7) for d in gaps]);assert h==h2 and a2<a
# A single scaling counterexample with fixed composition,adjacency and h.
one,h1,a1=readouts([pure[0],pure[1],pure[2]],[Q(1),Q(1)])
